# TPR and FPR functions
# Index 1 - biomarker, Index 2 - time
# Time dependent FPR
# P(Y > y | T > t) = P(h(Y) > h(y), h(T) > h(t)) / P(h(T) > h(t))
fpr <- function(ichl, hY, hT){
  
  # Matrix specifying lower and upper bounds for integral 
  lower <- upper <- matrix(0, nrow = 2, ncol = length(hY))
  lower[1, ] <- hY
  lower[2, ] <- hT
  upper[1, ] <- Inf
  upper[2, ] <- Inf
  jnt <- lpmvnorm(lower = lower, upper = upper,
                  invchol = ichl, w = pmvargs$w, logLik = FALSE)
  num <- exp(jnt)
  den <- pnorm(hT, lower.tail = FALSE)
  
  return(num / den)
}

# Time dependent TPR (cumulative)
# P(Y > y | T < t) = P(h(Y) > h(y), h(T) < h(t)) / P(h(T) < h(t))
tprc <- function(ichl, hY, hT){
  # Matrix specifying lower and upper bounds for integral 
  lower <- upper <- matrix(0, nrow = 2, ncol = length(hY))
  lower[1,] <- hY
  lower[2,] <- -Inf
  upper[1,] <- Inf
  upper[2,] <- hT
  # Evaluate integral
  jnt <- lpmvnorm(lower = lower, upper = upper, 
                  invchol = ichl, w = pmvargs$w, logLik = FALSE)
  num <- exp(jnt)
  den <- pnorm(hT)
  
  return(num / den)
}

# Time dependent TPR (incident)
# P(Y > y | T = t)
tpri <- function(ichl, hY, hT){
  # Matrix specifying conditioned variable (equality)
  cd <- cond_mvnorm(invchol = ichl,
                    which_given = 2,
                    given = matrix(hT, nrow = 1))
  # Univariate normal
  tpri <- pnorm(hY, mean = c(cd$mean), 
                sd = sqrt(c(diagonals(invchol2cov(cd$invchol)))),
                lower.tail = FALSE)
  
  return(tpri)
}

### Model to cumulative ROC curve
m2roc <- function(mm, nd){
  
  # Linear predictors / trafos
  nd$hY <- predict(mm, newdata = nd, margin = 1, type = "trafo")
  nd$hT <- predict(mm, newdata = nd, margin = 2, type = "trafo")
  
  ichl <-  coef(mm, type = "Lambda")
  nd$fpr <- fpr(ichl, nd$hY, nd$hT)
  nd$tprc <- tprc(ichl, nd$hY, nd$hT)
  
  return(nd)
}


