plt_survu <- function(yl, yu, ...){
  gTc <- seq(0, 75, length.out = 100)
  ndul <- expand.grid(yl, gTc)
  nduu <- expand.grid(yu, gTc)
  names(ndul) <- names(nduu) <- c(respY, respT)
  
  # Linear predictors / trafos
  hYl <- predict(mmu, newdata = ndul, margin = 1, type = "trafo")
  hYu <- predict(mmu, newdata = nduu, margin = 1, type = "trafo")
  hT <- predict(mmu, newdata = nduu, margin = 2, type = "trafo")
  ichl <-  coef(mmu, type = "Lambda")
  lower <- upper <- matrix(0, nrow = 2, ncol = length(hYl))
  lower[1,] <- hYl
  lower[2,] <- hT
  upper[1,] <- hYu
  upper[2,] <- Inf
  # Evaluate integral
  jnt <- lpmvnorm(lower = lower, upper = upper, 
                  invchol = ichl, w = pmvargs$w, logLik = FALSE)
  num <- exp(jnt)
  den <- pnorm(hYu) - pnorm(hYl)
  res <- num / den
  # KM curve
  kmh <- survfit(Stime ~ 1, data = subset(dat0, NFL >= yl & NFL < yu))
  lines(kmh, conf.int = FALSE, mark.time = TRUE, cex = 0.3, ...)
  lines(gTc, res, ...)
}

