## Confidence Intervals for modeled estimates
# Mean
cfu <- coef(mmu)
# Variance covariance matrix of the model
Vu <- vcov(mmu)
Vu <- (Vu + t(Vu)) / 2
# Simulate parameters
Pu <- rmvnorm(n_boot, mean = cfu, sigma = Vu)
mslu <- list(mYu, mTu)

# Parameter values to unconditional summary statistics
theta2sum <- function(theta){
  mms <- do.call(mmlt, c(mslu, theta = list(theta), data = list(dat0), dofit = FALSE))
  nduts <- m2roc(mms, ndut)
  aucus <- by(nduts, list(nduts$Stime), function(x) pracma::trapz(1-x$fpr, x$tprc), simplify = FALSE)
  aucus <- do.call(c, aucus)
  yius <- by(nduts, list(nduts$Stim), function(x) max(x$tprc - x$fpr), simplify = FALSE)
  yius <- do.call(c, yius)
  optus <- by(nduts, list(nduts$Stime), function(x) x[which.max(x$tprc - x$fpr), respY], simplify = FALSE)
  optus <- do.call(c, optus)
  
  ndut_opts <- data.frame(optus, tf)
  names(ndut_opts) <- c(respY, respT)
  ssus <- m2roc(mms, ndut_opts)
  sensus <- ssus$tprc
  specus <- 1 - ssus$fpr
  
  return(list(aucs = aucus, yis = yius, opts = optus, senss = sensus, specs = specus))
}

# Parametric bootstrap confidence intervals
sums <- mclapply(1:nrow(Pu), function(j) theta2sum(Pu[j, ]), mc.cores = 6)
prtci <- function(x,y) paste0("(",x,", ", y,")") 
sim2ci <- function(j){
  sumsj <- sapply(sums, function(x) x[[j]])
  sej <- sqrt(rowMeans((sweep(sumsj, 1, sumu[, j], "-"))^2))
  lwr <- sumu[, j] - qz * sej
  upr <- sumu[, j] + qz * sej
  lu <- format(round(cbind(lwr, upr), 2))
  return(apply(lu, 1, function(y) prtci(y[1], y[2])))
}
sumu_ci <- sapply(1:ncol(sumu), function(j) sim2ci(j))
sumur <- format(round(sumu, 2))
tb_sumu <- sapply(1:ncol(sumu), function(j) paste(sumur[, j], sumu_ci[, j]))
tb_sumu <- cbind(tf, tb_sumu)
colnames(tb_sumu) <- c("Time", "AUC (95% CI)", "Youden index (95% CI)", "Optimal threshold (95% CI)",
                       "Sensitivity (95% CI)", "Specificity (95% CI)")
cap_sumu <- ""
print(xtable(tb_sumu, align = "lrrrrrr", caption = cap_sumu, label = "tab:sumu"),
      include.rownames = FALSE, 
      booktabs = TRUE
)




