cf_hT <- cfs[ind_hT]
suppY <- attr(mY$model$model$bresponse, "variables")$support
suppT <- attr(mT$model$model$bresponse, "variables")$support

gpf <- function(theta, j, resp, nd, supp, ord, ...){
  bf <- Bernstein_basis(numeric_var(resp, support = supp, bounds = c(1e-10, Inf)), order = ord, ...)
  theta[j] <- 1
  theta[-j] <- 0
  prf <- predict(bf, newdata = nd, coef = theta)
}

plot_trafo <- function(grd, resp, supp, ord = 6, cf, ind, alpha = 0.05, ...){
  
  ndh <- list(grd)
  names(ndh) <- resp
  # Set up bernstein basis
  bb <- Bernstein_basis(numeric_var(resp, support = supp, bounds = c(1e-10, Inf)), 
                         order = ord, ui = "increasing", ...)
  pr_bb <- predict(bb, newdata = ndh, coef = cf)
  # Delta method
  # Derivative of the parameter transformation function
  gph <- sapply(1:(ord+1), gpf, theta = cf, resp = resp, nd = ndh, supp = supp, ord = ord, ...)
  # Select relevant covariances
  V_h <- V[ind, ind]
  sey <- sqrt(rowSums((gph %*% V_h) * gph))
  qz <- qnorm(alpha / 2, lower.tail = FALSE)
  # Pointwise Wald CIs
  lw <- pr_bb - sey * qz
  up <- pr_bb + sey * qz
  # Plot
  ylims <- c(floor(min(lw)), ceiling(max(up)))
  plot(grd, pr_bb, type = "l", ylim = ylims, ylab = "", xlab = "", las = 1)
  
  polygon(x = c(grd, rev(grd)), y = c(lw, rev(up)), col =  adjustcolor("grey50", alpha.f = 0.10), border = NA)
  rug(dat0[, resp])

}

