# Table for summary statistics (Youden index and AUC)
gdelFRS <- seq(0, 1, length.out = 100)
gY <- seq(limY[1], limY[2], length.out = 100)
ndsum <- expand.grid(tf, mAge, mSex, gC9, gdelFRS, mALSF, mSite)
names(ndsum) <- c("Time", covs)

# Grid
nd_ta <- expand.grid(gY, tf, mAge, mSex, gC9, gdelFRS, mALSF, mSite)
names(nd_ta) <- c(respY, respT, covs)
nd_tauc <- m2roc(mm, nd_ta)

# Calculate time-varying AUC
aucc <- by(nd_tauc, list(nd_tauc$Stime, nd_tauc$C9, nd_tauc$delFRS), function(x) pracma::trapz(1-x$fpr, x$tprc), simplify = FALSE)
aucc <- do.call(c, aucc)
ndsum$auc <- aucc


## Confidence bands for AUC
msl <- list(mY, mT)

# Parameter values to AUC
theta2aucs <- function(theta){
  mms <- do.call(mmlt, c(msl, theta = list(theta), data = list(dat0), dofit = FALSE))
  ndtas <- m2roc(mms, nd_ta)
  auccs <- by(ndtas, list(ndtas$Stime, ndtas$C9, ndtas$delFRS), function(x) pracma::trapz(1-x$fpr, x$tprc), simplify = FALSE)
  auccs <- do.call(c, auccs)
  return(auccs)
}

# Parametric bootstrap confidence intervals
aucs <- mclapply(1:nrow(P), function(j) theta2aucs(P[j, ]), mc.cores = 6)
aucss <- do.call(rbind, aucs)
se_auc <- sqrt(colMeans((sweep(aucss, 2, aucc, "-"))^2))
qz <- qnorm(1 - 0.05 / 2)
ndsum$lwr <- aucc - qz * se_auc
ndsum$upr <- aucc + qz * se_auc



ggplot(ndsum, aes(x = delFRS, y = auc, fill = C9)) +
  geom_line(aes(color = C9)) +
  geom_ribbon(data = ndsum, aes(ymin = lwr, ymax = upr, fill = C9), alpha = 0.1) +
  scale_color_manual(values = cols_hml[1:2]) +
  scale_fill_manual(values = cols_hml[1:2]) +
  facet_grid(~ Time, labeller = label_both) +
  theme_bw() +
  theme(legend.position = "top",
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black"),
        strip.background = element_rect(color = "black"),
        text = element_text(size = 12, color = "black"),
        axis.text = element_text(size = 8, color = "black"),
        strip.text.x = element_text(size = 12)) +
  ylab("AUC") +
  xlab(expression("Baseline"~Delta~"FRS")) + 
